<?php
declare(strict_types=1);
namespace Kios\MerchantOperations;

final class PlatformAdministrationView
{
    private static function h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
    private static function hidden(string $name,mixed $value):string{return '<input type="hidden" name="'.$name.'" value="'.self::h($value).'">';}
    private static function badge(string $s):string{return '<span class="pa-badge" data-status="'.self::h($s).'">'.self::h(str_replace('_',' ',$s)).'</span>';}
    private static function field(string $name,string $label,string $value='',string $type='text'):string{return '<label>'.self::h($label).'<input type="'.$type.'" name="'.$name.'" value="'.self::h($value).'"'.($name==='q'?'':' required').'></label>';}
    private static function table(array $headers,array $rows):string
    {
        $x='<div class="pa-table" tabindex="0" aria-label="Scrollable records"><table><thead><tr>';foreach($headers as$h)$x.='<th>'.self::h($h).'</th>';$x.='</tr></thead><tbody>';foreach($rows as$r){$x.='<tr>';foreach($r as$c)$x.='<td>'.$c.'</td>';$x.='</tr>';}if(!$rows)$x.='<tr><td colspan="'.count($headers).'">No matching records.</td></tr>';return $x.'</tbody></table></div>';
    }
    private static function form(string $csrf,array $m,string $op,string $title,string $fields):string
    {
        return '<details class="pa-action"><summary>'.self::h($title).'</summary><form method="post" data-pa-form>'.self::hidden('_csrf',$csrf).self::hidden('action','platform-admin').self::hidden('merchant',$m['merchant_id']).self::hidden('expected',$m['admin_version']).self::hidden('request',bin2hex(random_bytes(16))).self::hidden('op',$op).'<p class="pa-muted">Current administrative revision '.(int)$m['admin_version'].' · a stale form is rejected.</p>'.$fields.'<label>Reason<input name="reason" maxlength="240" required></label><label class="pa-confirm"><input type="checkbox" name="confirm" value="yes" required>I confirm this authorized synthetic administrative change.</label><button>Confirm change</button></form></details>';
    }
    private static function select(string $name,string $label,array $options,string $selected=''):string
    {
        $x='<label>'.self::h($label).'<select name="'.$name.'">';foreach($options as$v=>$text)$x.='<option value="'.self::h($v).'"'.((string)$v===$selected?' selected':'').'>'.self::h($text).'</option>';return $x.'</select></label>';
    }
    private static function events(array $events):string
    {
        $rows=[];foreach($events as$e)$rows[]=[self::h($e['merchant_name']??''),self::h($e['version']),self::h($e['operation']),self::h($e['reason']),self::h($e['actor_id']),self::h(gmdate('d M Y H:i',$e['created_epoch']).' UTC')];return self::table(['Merchant','Revision','Action','Reason','Authenticated actor','Recorded'],$rows);
    }
    private static function pages(int $page,int $pages,string $query):string
    {
        $x='<nav class="pa-pages" aria-label="Record pages"><span>Page '.$page.' of '.$pages.'</span>';if($page>1)$x.='<a href="'.$query.'&amp;page='.($page-1).'">Previous</a>';if($page<$pages)$x.='<a href="'.$query.'&amp;page='.($page+1).'">Next</a>';return $x.'</nav>';
    }
