        foreach(['overview'=>'Overview','merchants'=>'Merchants','outlets'=>'Outlets','subscriptions'=>'Subscriptions','audit'=>'Security & audit','create'=>'Create merchant']as$k=>$v)$x.='<a href="/merchant.php?platform='.$k.'"'.($section===$k?' aria-current="page"':'').'>'.$v.'</a>';
        if(IntegratedSetup::enabled())$x.='<a href="/merchant.php?platform=merchants">Guided setup: select merchant → outlets</a>';
        if(UsageBilling::enabled())$x.='<a class="pa-usage-link" href="/merchant.php?usage_platform=1">Usage &amp; pricing</a>';
        $x.='</nav><form method="post">'.self::hidden('_csrf',$csrf).self::hidden('action','logout').'<button class="pa-secondary">Sign out</button></form><p class="pa-safety">Synthetic data only<br>No public registration<br>No real payments</p></aside><main data-platform-console="'.self::h($section).'"><header class="pa-header"><div><p class="pa-eyebrow">KIOS / PLATFORM OPERATIONS</p><h1>'.self::h($titles[$section]).'</h1></div><span class="pa-private">PRIVATE DEMO</span></header><p class="pa-banner">Customer ordering CLOSED · Payments, commercial charges and physical printing DISABLED</p>';
