        if($section==='overview'){
            $status=array_column($d['statuses'],'n','status');$x.='<section class="pa-metrics" aria-label="Authoritative platform totals">';foreach(['Configured merchants'=>$d['merchants'],'Active demonstrations'=>(int)($status['ACTIVE_DEMO']??0),'Configured outlets'=>$d['outlets'],'Pending owner setup / review'=>$d['pending'],'Trial subscriptions'=>$d['phases']['TRIAL']??0,'Suspended subscriptions'=>$d['phases']['SUSPENDED']??0]as$label=>$v)$x.='<article><span>'.self::h($label).'</span><strong>'.(int)$v.'</strong></article>';$x.='</section><div class="pa-two"><section class="pa-panel"><h2>Merchants by plan</h2><p class="pa-muted">Native active merchant records; unassigned merchants are shown separately in the directory.</p>';foreach($d['plans']as$p=>$n)$x.='<p class="pa-stat"><span>'.self::h($p).'</span><strong>'.(int)$n.'</strong></p>';$x.='</section><section class="pa-panel"><h2>Administrative access</h2>';foreach($d['statuses']as$s)$x.='<p class="pa-stat">'.self::badge($s['status']).'<strong>'.(int)$s['n'].'</strong></p>';$x.='</section></div><section class="pa-panel"><h2>Recent authorized activity</h2>'.self::events($d['activity']).'</section>';
        }elseif($section==='merchants'){
            $x.='<section class="pa-panel"><form method="get" class="pa-filter">'.self::hidden('platform',$section).self::field('q','Merchant name or reference',$d['query']).self::select('status','Administrative status',[''=>'All statuses','PROVISIONING'=>'Provisioning','ACTIVE_DEMO'=>'Active demonstration','SUSPENDED'=>'Suspended','ARCHIVED'=>'Archived'],$d['status']).'<button>Search</button></form><p>'.(int)$d['total'].' matching merchants · up to 20 per page</p>';
            $rows=[];foreach($d['merchants']as$m){$s=$m['subscription'];$link='<a class="pa-record" href="/merchant.php?platform=detail&amp;merchant='.self::h($m['merchant_id']).'">'.self::h($m['name']).'</a><small>'.self::h($m['merchant_id']).'</small>';$rows[]=[$link,self::badge($m['status']),(string)(int)$m['outlets'],$s?self::h($s['assignment']['name']).'<br>'.self::badge($s['state']):'Unmanaged / unassigned',self::h($m['setup_progress']??$m['onboarding_status']??'Not initialized'),$m['last_activity']?self::h(gmdate('d M H:i',$m['last_activity']).' UTC'):'No administrative action recorded'];}
            $x.=self::table(['Merchant / reference','Access','Outlets','Subscription','Onboarding','Last administrative activity'],$rows).self::pages($d['page'],$d['pages'],'?platform='.$section.'&amp;q='.rawurlencode($d['query']).'&amp;status='.rawurlencode($d['status'])).'</section>';
