            $x.='<section class="pa-panel"><h2>Subscription &amp; entitlements</h2>';if($d['subscription'])$x.='<p>'.self::h($d['subscription']['assignment']['name']).' · pinned v'.(int)$d['subscription']['assignment']['plan_version'].' '.self::badge($d['subscription']['state']).'</p><p>Current period ends '.self::h(gmdate('d M Y H:i',$d['subscription']['assignment']['expires_epoch'])).' UTC.</p>';
            else$x.='<p>No managed lifecycle assigned.</p>';
            $x.='<a class="pa-button" href="/merchant.php?plans=1#lifecycle">Manage plans, lifecycle &amp; scheduled changes</a><p class="pa-muted">Uses the existing M06A/M06B engine. No charges or financial obligations.</p></section><section class="pa-panel"><h2>Outlets</h2><p>Native scope and customer menu categories remain independent of platform administration.</p><div class="pa-outlets">';
            $options=[];foreach($d['outlets']as$o){$options[$o['outlet_id']]=$o['name'];if(IntegratedSetup::enabled())$x.='<p><a class="pa-button" href="/merchant.php?outlet_wizard=1&amp;platform_setup=1&amp;merchant='.self::h($m['merchant_id']).'&amp;outlet='.self::h($o['outlet_id']).'">Configure &amp; review '.self::h($o['name']).'</a></p>';$x.='<article><div class="pa-heading"><h3>'.self::h($o['name']).'</h3>'.self::badge($o['admin_status']).'</div><p class="pa-reference">'.self::h($o['outlet_id']).'</p><p>Native mapping '.self::h($o['legacy_outlet_id']??'Not mapped').' · '.self::h($o['opening_time']??'').'–'.self::h($o['closing_time']??'').' · Shop '.((int)($o['manual_enabled']??0)?'requires review':'CLOSED').'</p>';
                if($o['legacy_outlet_id']){$x.=self::form($csrf,$m,'outlet-status','Restrict / restore this outlet',self::hidden('data[outlet]',$o['outlet_id']).self::select('data[status]','Outlet access',['ACTIVE_DEMO'=>'Active demonstration','SUSPENDED'=>'Suspend new work','ARCHIVED'=>'Archive completed outlet']));$x.=self::form($csrf,$m,'outlet-update','Edit closed outlet configuration',self::hidden('data[outlet]',$o['outlet_id']).self::field('data[name]','Outlet name',$o['name']).'<div class="pa-two">'.self::field('data[opening]','Opening time',substr($o['opening_time'],0,5),'time').self::field('data[closing]','Closing time',substr($o['closing_time'],0,5),'time').'</div>');}$x.='</article>';
