            $rows=[];foreach($d['administrators']as$a)$rows[]=[self::h($a['display_name']),self::h($a['role_code']),self::h($a['outlet_id']??'Merchant-wide owner'),$a['active']?'Active':'Inactive'];$x.=self::table(['Identity','Role bundle','Scope','Membership'],$rows);
            if($d['eligibleStaff']){$staff=[];foreach($d['eligibleStaff']as$s)$staff[$s['user_id']]=$s['display_name'].' · '.$s['username'];$fields=self::select('data[user]','Existing native staff identity',$staff).self::select('data[outlet]','Authorized outlet scope',$options).self::select('data[role]','Reviewed role bundle',['outlet_administrator'=>'Outlet administrator','cashier'=>'Cashier','kitchen'=>'Kitchen']).self::select('data[active]','Membership access',['1'=>'Active','0'=>'Inactive']);$x.=self::form($csrf,$m,'administrator','Manage scoped administrator / staff permissions',$fields);}else$x.='<p class="pa-muted">No eligible native staff account is available. Owners create and activate staff through the existing attended staff setup. Owner transfer and credential recovery are not performed here.</p>';
            $x.='</section><section class="pa-panel"><h2>Merchant administration history</h2>'.self::events($d['events']).'</section>';
        }elseif($section==='subscriptions'){
